import{_ as a,a0 as l,w as r,s as i,ao as m,I as o,x as s,a1 as p,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"命令列星期二——第五部分 | LCTT x X-CMD","titleTemplate":false,"description":"命令列星期二——第五部分 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列星期二——第五部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列星期二——第五部分 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/Command Line Tuesdays – Part Five","title":"命令列星期二——第五部分","tag":"201407","desc":""},"relativePath":"201407/Command Line Tuesdays – Part Five.md","filePath":"[post].md"}'),d={name:"201407/Command Line Tuesdays – Part Five.md"};function g(h,t,u,T,C,f){const e=l("Link");return r(),i("div",null,[t[11]||(t[11]=m('<h1 id="命令列星期二——第五部分" tabindex="-1">命令列星期二——第五部分 <a class="header-anchor" href="#命令列星期二——第五部分" aria-label="Permalink to “命令列星期二——第五部分”">​</a></h1><p>對，你也許已經猜到了又是我們相見的時候了。這一次我們將會學習如何使用命令工作。因此，事不宜遲，我們直入正題吧。</p><p>肖茨先生指出，到現在為止，我們學習了一些神奇的命令及其參數和選項，而今天正是我們揭開他們那神秘面紗一角的一天。我們將會學習如下的一些命令及其作用：type, which, help和man。但是在此之前，我麼先學習一下——</p><p>###什麼是命令？###</p><p>我們可以將<strong>命令</strong>分為四個種類。</p><p><strong>1）可執行的程序：</strong>命令可以是一個可執行程序。如果你在前面的課程中有遍歷過你的系統，這也是你應該做的。你也許已經發現了/user/bin這個目錄，你看到很多的像transmission-gtk, deluge-gtk等的名字。對我們新手來説，現在這些可以編譯成二進制文件或者用腳本語言編寫的可執行程序具體是什麼並不太重要。重點是，他們是可執行文件，你可以運行它們。找到/user/bin這個目錄，列出裏面的文件，隨便挑一個去運行它。</p><p><strong>2）shell內置命令：</strong> bash提供了一系列的shell內置命令，例如，cd命令就是一個shell內置命令。</p><p><strong>3）shell函數：</strong>內置於系統環境中的小型的shell腳本。現在我們簡單的提及一下它，因為在後面的幾個星期中我們將要學習它。</p><p><strong>4）別名：</strong>你可以基於其他命令定義你自己的命令。我們也會在後面的課程中學習到。</p><p>現在，知道我們要處理的命令的哪一類是有意義的。我們可以使用<strong>type</strong>命令查看。</p><p>###type###</p><p>你可以使用<strong>type + command</strong>來查看你要使用的命令屬於什麼類型。你只要輸入type command就可以得到命令類型的輸出，如下：</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Zaslonska-slika-2014-07-15-091448.png" alt="type mkdir"></p><p>或者</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Zaslonska-slika-2014-07-15-091640.png" alt="type ls"></p><p>從上面例子可以看出‘ls’命令實際上是‘_ls’的別名。（LCTT譯註：不同機器上的別名定義可能不同，比如RedHat/Centos系列上，ls實際上是‘ls --color=auto’的別名，而這個‘_ls’想必是openSUSE上的情況。）</p><p>###which###</p><p>有時（雖然在桌面系統中很少會出現這種情況），在一台機器中存在一個可執行程序的多個版本。為了找到某個可執行程序的準確位置，我們可以使用which命令。which命令只對可執行程序有用。</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Zaslonska-slika-2014-07-15-092052.png" alt="which transmission-gtk"></p><p>如今，多數的命令都會附帶説明文檔，因此，當你在沒有網絡的的情況下使用命令列時，你不能在論壇或者IRC上提問，但是你又必須要知道某個命令的準確用法。此時你有兩種解決方法，第一個是——</p><p>###help###</p><p>help命令對shell內置命令有用（在上面的第二類中我們有提到過）。所以，你可以選擇一個shell內置命令為例，如cd，簡單的輸入help cd即可。你會得到一個有用的頁面，去試一下看cd為我們提供了什麼功能。該頁面列出了該命令的用法和可選項（選項列在方括號中，表明它們是可選的，如果方括號中有垂直分隔符分隔某些選項，則這些選項是互斥的，不要同時使用他們！）</p><p>###--help###</p><p>（LCTT譯註：Linux上的命令中，通常單字符參數前使用一個破折號，而多個字符的長參數則使用兩個破折號，原文此處用的是“-help”，實際上這種情況很少，所以修正為“--help”）</p><p>help只對shell內置命令有用。但是很多的可執行程序有--help選項。其作用類似於help命令，但是你必須在你要查看幫助的命令後輸入 --help。例如，transmission-gtk --help。試一下看在改該可執行程序中有什麼可選項可以使用。</p><p>###man###</p><p>多數的可執行程序都提供一個正式發説明文檔。你可以使用man命令查看這份説明文檔。試一下只輸入man program，看有什麼輸出。在你的系統中隨便找一個程序去嘗試一下。例如，我們試一下man transmission-gtk。你會打開了一個由目錄分割的文件。這個文件包含該程序是什麼、做什麼和你可以怎樣去使用它等的信息。但是這個文件並沒有提供使用範例，因為它不是一個指導手冊。（LCTT譯註，man裏面有時候也會帶有一些範例，但是往往不會很詳細，另外還有一個info命令，通常能得到更多的使用幫助。不過真正理解每個命令的各種用户，還是要多查閲各種資料，並親自試驗才行。）</p><p>這周我們就到先講這裏了。</p><p>我想再花一分鐘來感謝大家對本節的建議和貢獻。是你們讓這個系列的文章變得越來越好，我希望在你們的幫助下，我們這些新用户在夏季結束前可以使用基本的命令列工具。你們是最棒的。像我一樣的新用户們，我們都會感到失落，堅持到底，我們的付出總會有回報的！</p><hr>',30)),o("p",null,[t[1]||(t[1]=s("via: ",-1)),p(e,{href:"https://news.opensuse.org/2014/07/15/command-line-tuesdays-part-five/"},{default:n(()=>[...t[0]||(t[0]=[s("https://news.opensuse.org/2014/07/15/command-line-tuesdays-part-five/",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=s("譯者：",-1)),p(e,{href:"https://github.com/cvsher"},{default:n(()=>[...t[2]||(t[2]=[s("cvsher",-1)])]),_:1}),t[5]||(t[5]=s(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[3]||(t[3]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=s("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[6]||(t[6]=[s("LCTT",-1)])]),_:1}),t[9]||(t[9]=s(" 原創翻譯，",-1)),p(e,{href:"http://linux.cn/"},{default:n(()=>[...t[7]||(t[7]=[s("Linux中國",-1)])]),_:1}),t[10]||(t[10]=s(" 榮譽推出",-1))])])}const x=a(d,[["render",g]]);export{w as __pageData,x as default};
